package com.careeragent.interview.agent;
import com.baomidou.mybatisplus.core.toolkit.Wrappers;import com.careeragent.domain.entity.*;import com.careeragent.mapper.UserInterviewMemoryMapper;import java.util.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor class InterviewMemoryManager{private final UserInterviewMemoryMapper mapper;void rememberProfile(Long userId,String direction,ResumeResult resume){var memory=current(userId);memory.setTargetDirections(merge(memory.getTargetDirections(),List.of(direction)));memory.setTechnicalSkills(merge(memory.getTechnicalSkills(),resume.technicalSkills()));save(memory);}void rememberReport(Long userId,ReportResult report){var memory=current(userId);memory.setRecurringStrengths(merge(memory.getRecurringStrengths(),split(report.strength())));memory.setRecurringWeaknesses(merge(memory.getRecurringWeaknesses(),split(report.weakness())));save(memory);}private UserInterviewMemory current(Long userId){var value=mapper.selectOne(Wrappers.<UserInterviewMemory>lambdaQuery().eq(UserInterviewMemory::getUserId,userId));if(value==null){value=new UserInterviewMemory();value.setUserId(userId);value.setTargetDirections(List.of());value.setTechnicalSkills(List.of());value.setRecurringStrengths(List.of());value.setRecurringWeaknesses(List.of());}return value;}private void save(UserInterviewMemory value){if(value.getId()==null)mapper.insert(value);else mapper.updateById(value);}private List<String> merge(List<String>a,List<String>b){var result=new LinkedHashSet<String>();result.addAll(Optional.ofNullable(a).orElse(List.of()));result.addAll(Optional.ofNullable(b).orElse(List.of()));return result.stream().filter(v->v!=null&&!v.isBlank()).limit(30).toList();}private List<String> split(String value){return Arrays.stream(Objects.toString(value,"").split("[；;]")).map(String::trim).filter(v->!v.isBlank()).toList();}}
